pred_sql:
SELECT c.promoTypes
FROM cards c
WHERE c.name = 'Duress';

SELECT id
FROM cards
WHERE duelDeck = 'a';

SELECT c.availability
FROM cards c
WHERE c.artist = 'Daren Bader';

SELECT subtypes, supertypes
FROM cards
WHERE name = 'Molimo, Maro-Sorcerer';

SELECT c.artist
FROM cards c
WHERE c.flavorName = 'Battra, Dark Destroyer';

SELECT s.mcmName
FROM sets s
WHERE s.releaseDate = '2017-06-09';

SELECT COUNT(Id) AS number_of_revival_badges
FROM badges
WHERE Name = 'Revival';

SELECT COUNT(*) 
FROM gasstations 
WHERE Country = 'CZE' AND Segment = 'Premium';

SELECT 
    (SUM(CASE WHEN l.status = 'A' THEN l.amount ELSE 0 END) * 100.0 / SUM(l.amount)) AS percentage
FROM loan l;

SELECT COUNT(DISTINCT driverId) 
FROM driverStandings 
WHERE raceId = 18;

SELECT ds.wins
FROM driverStandings ds
WHERE ds.position = 91;

SELECT COUNT(*) 
FROM member 
WHERE position = 'President';

SELECT a.element
FROM atom a
WHERE a.atom_id = 'TR000_1';
